mapper.select:
SELECT VBB.BOOKSET_ID as booksetId, VBT.BOOKSET_NAME as booksetName, VBB.BALANCE_DATE as bookDate, VBB.SUBJECT_NO as subjectNo, VBB.O_CCY as oCcy, VBB.NUM_AMT as numAmt, VBB.O_AMT as oAmt, VBB.BAL_FLAG as balFlag, CASE WHEN VBB.SUBJECT_LEVEL = #{maxSubjectLevel} THEN VBS2.SUBJECT_TYPE ELSE VBS.SUBJECT_TYPE END as subjectType, VBB.SUBJECT_LEVEL as subjectLevel, CASE WHEN VBB.SUBJECT_LEVEL = #{maxSubjectLevel} THEN VBBD.DETAIL_SUBNAME_TAIL ELSE VBS.SUBJECT_NAME END as subjectName, CASE WHEN VBB.SUBJECT_LEVEL = #{maxSubjectLevel} THEN VBS2.BASE_SUBJECT_NATURE ELSE VBS.BASE_SUBJECT_NATURE END as baseSubjectNature, VBB.FSUBJECT_NO as fsubjectNo, VBBD.DETAIL_SUBJECT_NO_TAIL detailSubjectNoTail, VBB.B_CCY, VBB.B_AMT /** add by yanya on 20200221 增加负债共同类 科目余额方向 case when 科目余额.科目级别 = 全局变量【底层科目级别】then 账套科目2.余额方向 else 账套科目.余额方向 end as 科目期待余额方向 **/ ,case when VBB.SUBJECT_LEVEL = #{maxSubjectLevel} then VBS2.BAL_FLAG else VBS.BAL_FLAG end expectBalFlag /** add by weipeng on 20220331 增加估值方案落地表关联 start **/ ,schemeInfo.VALUATION_METHOD as valuationMethod /** add by weipeng on 20220331 增加估值方案落地表关联 end **/ FROM BOK_BALANCE VBB
LEFT JOIN BOK_BOOKSET VBT ON VBB.BOOKSET_ID = VBT.BOOKSET_ID
LEFT JOIN BOK_SUBJECT VBS ON VBT.BOOKSET_ID_TMPL = VBS.BOOKSET_ID AND VBB.SUBJECT_NO = VBS.SUBJECT_NO
LEFT JOIN BOK_SUBJECT VBS2 ON VBT.BOOKSET_ID_TMPL = VBS2.BOOKSET_ID AND VBB.FSUBJECT_NO=VBS2.SUBJECT_NO LEFT JOIN BOK_BUSS_DETSUB VBBD ON VBB.BOOKSET_ID = VBBD.BOOKSET_ID AND VBB.SUBJECT_NO = VBBD.DETAIL_SUBJECT_NO /** add by weipeng on 20220331 增加估值方案落地表关联 start **/ LEFT JOIN BOK_FINPROD_SCHEME_INFO schemeInfo ON schemeInfo.BOOKSET_ID = VBBD.BOOKSET_ID AND schemeInfo.FINPROD_ID = VBBD.DETAIL_SUBJECT_NO_TAIL /** add by weipeng on 20220331 增加估值方案落地表关联 end **/ WHERE VBB.BALANCE_DATE = #{bookDate} AND VBB.BOOKSET_ID = #{booksetId} AND ( VBS.SUBJECT_TYPE IN
#{subjectType}
OR VBS2.SUBJECT_TYPE IN
#{subjectType}
) AND ( VBB.IS_LEAF = 'Y' OR ( VBS.BASE_SUBJECT_NATURE IN
#{fairValChange}
AND VBS.SUBJECT_LEVEL = 3
and VBS.SUBJECT_TYPE != '03' /**账套科目.科目类型 != '共同类'**/ ) )
ORDER BY VBB.BOOKSET_ID,VBB.SUBJECT_NO,VBB.O_CCY

SELECT ROUND(SUM(10000*PROFIT_AMT/CAPITAL),12) AS PYieldSumSince FROM ( SELECT P_YIELD, CAPITAL, PROFIT_AMT, row_number() over ( PARTITION BY BOOKSET_ID, HAPPEN_DATE ORDER BY BOOKSET_DATE DESC ) rn FROM BOK_STAT_BOK_POSITION A WHERE A.HAPPEN_DATE <= #{bookDate}
AND A.HAPPEN_DATE > #{queryDate}
AND A.BOOKSET_ID = #{booksetId} AND A.BOOK_DATE <= #{bookDate} AND A.CAPITAL != 0 AND A.CAPITAL IS NOT NULL ) WHERE rn = 1

SELECT SUM(END_DAYS_1*TDY_COST_AMT) AS remainTermSum, SUM(END_DAYS_2*TDY_COST_AMT) AS remainDurationSum, SUM(TDY_COST_AMT) AS costSum FROM ( SELECT NVL(A.END_DAYS_1,0) AS END_DAYS_1, NVL(A.END_DAYS_2,0) AS END_DAYS_2, CASE WHEN A.FINPROD_TYPE = #{finprodType} THEN NVL(A.END_DAYS_COST_AMT,0) ELSE NVL(A.TDY_COST_AMT,0) END AS TDY_COST_AMT, ROW_NUMBER() OVER (PARTITION BY A.BOOKSET_ID, A.HAPPEN_DATE, A.BOK_DETAIL_ID ORDER BY A.BOOK_SUMMARY_ORDER DESC) rn FROM BOK_STAT_DET_POSIITON A WHERE A.HAPPEN_DATE = #{bookDate} AND A.BOOKSET_ID = #{booksetId} AND A.BOOK_DATE <= #{bookDate} AND A.FINPROD_TYPE IN
#{item}
) WHERE rn = 1

SELECT SUM(balance) AS recvBalance FROM ( SELECT A.O_AMT_HAPPEN_DATE as balance, ROW_NUMBER() OVER(PARTITION BY A.BOOKSET_ID, A.BASE_SUBJECT_NATURE, A.BOK_DETAIL_ID, A.BRANCH, A.O_CCY ORDER BY A.BOOK_ORDER DESC ) AS RW FROM BOK_BOOKDETAIL_CURRENT A INNER JOIN BOK_DETAIL_ID B ON A.BOOKSET_ID = B.BOOKSET_ID AND A.BUSI_ID = B.BUSI_ID AND B.BUSI_DETAIL_TYPE = #{finprodType} WHERE A.BOOKSET_ID = #{booksetId} AND A.BOOK_DATE <= #{bookDate} AND A.HAPPEN_DATE <= #{bookDate} AND A.BASE_SUBJECT_NATURE IN
#{baseSubNature}
) WHERE RW = 1

SELECT A.BOOKSET_ID as booksetId, A.BALANCE_DATE as bookDate, A.SUBJECT_NO as subjectNo, A.NUM_AMT as numAmt, A.BAL_FLAG AS balFlag, A.O_AMT as oAmt, A.B_AMT as bAmt, C.BASE_SUBJECT_NATURE AS baseSubjectNature, D.DETAIL_SUBNAME_TAIL as subjectName, D.DETAIL_SUBJECT_NO_TAIL AS detailSubjectNoTail FROM BOK_BALANCE A LEFT JOIN BOK_BOOKSET B ON B.BOOKSET_ID = A.BOOKSET_ID LEFT JOIN BOK_SUBJECT C ON B.BOOKSET_ID_TMPL = C.BOOKSET_ID AND A.FSUBJECT_NO = C.SUBJECT_NO LEFT JOIN BOK_BUSS_DETSUB D ON D.BOOKSET_ID = A.BOOKSET_ID AND D.DETAIL_SUBJECT_NO = A.SUBJECT_NO WHERE A.BALANCE_DATE = #{bookDate} AND A.BOOKSET_ID = #{booksetId}
AND C.BASE_SUBJECT_NATURE IN
#{item}
AND A.SUBJECT_LEVEL = #{maxSubjectLevel}
AND B.ACCT_SUBJECT_ID != D.DETAIL_SUBJECT_NO ORDER BY A.BOOKSET_ID,A.SUBJECT_NO,C.BASE_SUBJECT_NATURE

SELECT ROUND(SUM(10000*PROFIT_AMT/CAPITAL),12) AS PYieldSumSince FROM ( SELECT P_YIELD, CAPITAL, PROFIT_AMT, row_number() over ( PARTITION BY BOOKSET_ID, HAPPEN_DATE ORDER BY BOOKSET_DATE DESC ) rn FROM BOK_STAT_BOK_POSITION A WHERE A.HAPPEN_DATE <= #{bookDate}
AND A.HAPPEN_DATE > #{queryDate}
AND A.BOOKSET_ID = #{booksetId} AND A.BOOK_DATE <= #{bookDate} AND A.CAPITAL != 0 AND A.CAPITAL IS NOT NULL
AND A.LAYERING_ID = #{layeringId}
) WHERE rn = 1

WITH FINPROD AS ( SELECT A.BOOKSET_ID, A.BUSI_ID, A.BUSI_DETAIL_TYPE, A.VDATE, A.BRANCH, B.CASH_ID FROM BOK_ACCT_LAYERING_INFO A, FIN_CASH_INFO B ,BOK_BOOKSET C WHERE A.BUSI_ID = B.FINPROD_ID
AND A.BRANCH = B.BRANCH AND A.BOOKSET_ID = C.BOOKSET_ID AND B.CASH_TYPE_2 = 'C04' AND A.BOOKSET_ID = #{booksetId} AND C.ACCT_SUBJECT_ID = #{acctSubjectId}
AND A.LAYERING_ID = #{layeringId}
) SELECT A.BOOKSET_ID booksetId, A.BUSI_ID busiId, A.BUSI_DETAIL_TYPE busiDetailType, A.VDATE vDate, A.BRANCH branch, A.CASH_ID cashId, A.BASIS basis FROM ( SELECT FINPROD.BOOKSET_ID, FINPROD.BUSI_ID, FINPROD.BUSI_DETAIL_TYPE, FINPROD.VDATE, FINPROD.BRANCH, FINPROD.CASH_ID, D.BASIS, ROW_NUMBER() OVER (PARTITION BY D.CASH_ID ORDER BY D.EFF_DATE DESC) AS newResult
FROM FIN_FLOAT_CALC_RULE D,FINPROD
WHERE D.CASH_ID = FINPROD.CASH_ID AND D.EFF_DATE <= #{bookDate} ) A WHERE newResult = 1

    SELECT
	    A.TAX_AMT_SUM as taxAmtSum,
	    A.TAX_AMT as taxAmt
	FROM 
	    TAX_BOK_BALANCE_SUM A
	WHERE A.BOOKSET_ID = #{booksetId}
	AND   A.HAPPEN_DATE = #{bookDate}
	AND   A.VAT_TYPE = #{vatType}
	AND   A.TAX_P_TYPE = #{taxPType}
